public class DateTimeZone_forID_TriageGen1Test {







    @Test
    public void testForID_PositiveOffset() {
        // Test a positive offset like +05:00
        // The method logic: if starts with + or -, it parses offset.
        // If offset is not 0, it returns fixedOffsetZone.
        DateTimeZone zone = DateTimeZone.forID("+05:00");
        assertNotNull(zone);
        // Note: internal implementation might normalize the ID string via printOffset
        assertTrue(zone.getOffset(0) == 5 * 3600);
    }








}

